/*SELECT  [PS Rpt V2 Recordset1 Slots].GroupID,  [PS Rpt V2 Recordset1 Slots].Dealer,  [PS Rpt V2 Recordset1 Slots].[Prod Date] AS Week,  [PS Rpt V2 Recordset1 Slots].[Prod Date],   --Format([Prod Date],"mmm/dd") AS [Day],   --Format([Prod Date],"dddd") AS DayOfWeek,   [PS Rpt V2 Recordset1 Slots].[Prod Line],  [PS Rpt V2 Recordset1 Slots].[Quote#],   [PS Rpt V2 Recordset1 Slots].[WO#],  [PS Rpt V2 Recordset1 Slots].InputField1,   [PS Rpt V2 Recordset1 Slots].InputField2,  [PS Rpt V2 Recordset1 Slots].[Steel Kit WO#],  [PS Rpt V2 Recordset1 Slots].[GN WO#],  [PS Rpt V2 Recordset1 Slots].Other,  [PS Rpt V2 Recordset1 Slots].[Other WO#],  [PS Rpt V2 Recordset1 Slots].[Beam WO#],  [PS Rpt V2 Recordset1 Slots].[Steel Kit WO#],   [PS Rpt V2 Recordset1 Slots].JobStartDate,  [PS Rpt V2 Recordset1 Slots].LO,   --Right([WO#],4) AS WO,  [Prod Sched Version#].[Version#],  [Prod Sched Version#].VDate,  [PS Rpt V2 Recordset1 Slots].[Stock/Sold],   [PS Rpt V2 Recordset1 Slots].[Slot#],   [PS Rpt V2 Recordset1 Slots].NoDays,   --IIf(IsNull([WO#]) And Not IsNull([Slot#]),"Slot# " & [Slot#],[WO#]) AS QuoteSlot,  [PS Rpt V2 Recordset1 Slots].HighRiskUnit,  [PS Rpt V2 Recordset1 Slots].IsGavlanized,  [PS Rpt V2 Recordset1 Slots].GalvIndicator FROM  [BWSdb].[dbo].[Prod Sched Version#] CROSS JOIN (  SELECT    [Prod Sched].GroupID,   Dealers.[COMPANY NAME] AS Dealer,   [Prod Sched].[Prod Date] AS Week,   [Prod Sched].[Prod Date],   Format([Prod Date],"mmm/dd") AS [Day],   Format([Prod Date],"dddd") AS DayOfWeek,   [Prod Sched].[Prod Line],   [Prod Sched].[Quote#],   [Prod Sched].[WO#],   [Prod Sched].InputField1,   [Prod Sched].InputField2,   [Prod Sched].LO,   Right([Prod Sched].[WO#],4) AS WO,   [Prod Sched].[GN WO#],   [Prod Sched].Other,   [Prod Sched].[Other WO#],   [Prod Sched].[Beam WO#],   [Prod Sched].[Steel Kit WO#],   [Prod Sched].JobStartDate,   [Prod Sched].[Stock/Sold],   [Prod Sched].[Slot#],   [Prod Sched].NoDays,   [Prod Sched].HighRiskUnit,   [Prod Sched].IsGavlanized,   [Prod Sched].GalvIndicator  FROM    [BWSdb].[dbo].[PS Rpt V2]  LEFT JOIN (   [BWSdb].[dbo].Orders  LEFT JOIN    [BWSdb].[dbo].Dealers  ON    Orders.DealerID=Dealers.ID  )   ON    [Prod Sched].[Quote#]=Orders.[Quote#]  ORDER BY [Prod Sched].LO;  ) AS [PS Rpt V2 Recordset1 Slots] ORDER BY  [PS Rpt V2 Recordset1 Slots].LO;*/SELECT * FROM [BWSdb].[dbo].[Orders]--SELECT * FROM [BWSdb].[dbo].[OrdersV2]  exec [BWSdb].[dbo].[sp_ProductionSchedule V4_Slots] '2024-01-01', '2024-12-31';SELECT	*FROM	[BWSdb].[dbo].[dtProductionSchedule] AS [PS];SELECT	[PL].[Prod Line]FROM	[BWSdb].[dbo].[dtProductionSchedule] AS [PS]INNER JOIN	[BWSdb].[dbo].[Prod Lines] AS [PL]ON	(CASE 		WHEN [PS].[WO Line 1] IS NOT NULL THEN			(CASE WHEN [PS].[WO Line 1] = [PL].[Prod Line] THEN 1 ELSE 0 END)		WHEN [PS].[WO Line 2] IS NOT NULL THEN			(CASE WHEN [PS].[WO Line 2] = [PL].[Prod Line] THEN 1 ELSE 0 END)		WHEN [PS].[Other Line] IS NOT NULL THEN			(CASE WHEN [PS].[Other Line] = [PL].[Prod Line] THEN 1 ELSE 0 END)		WHEN [PS].[GN Line] IS NOT NULL THEN			(CASE WHEN [PS].[GN Line] = [PL].[Prod Line] THEN 1 ELSE 0 END)		WHEN [PS].[Beam Line] IS NOT NULL THEN			(CASE WHEN [PS].[Beam Line] = [PL].[Prod Line] THEN 1 ELSE 0 END)		ELSE 0	END) > 0WHERE	[PL].[LO] IS NOT NULLGROUP BY	[PL].[Prod Line]	,[PL].[LO]ORDER BY	[PL].[LO]; SELECT	*FROM	--[BWSdb].[dbo].[Prod Lines Out]	[BWSdb].[dbo].[Prod Lines]ORDER BY	[LO]